use serde::Deserialize;
use std::collections::{HashMap, HashSet};

/// The authored Species Search normalization contract JSON.
pub const CONTRACT_SOURCE: &str =
    include_str!("../../canopi-types/species-search-normalization.json");
/// The pinned Unicode facts JSON generated by `scripts/species_search_unicode_facts.py`.
pub const UNICODE_FACTS_SOURCE: &str =
    include_str!("../../canopi-types/species-search-unicode-15.json");
/// The expected Unicode facts filename referenced by the contract.
pub const UNICODE_FACTS_FILENAME: &str = "species-search-unicode-15.json";

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct NormalizationContract {
    pub(crate) contract_format_version: u32,
    pub(crate) normalization_version: u32,
    pub(crate) unicode_data: UnicodeDataReference,
    pub(crate) algorithm: NormalizationAlgorithm,
    pub(crate) corpus: Vec<CorpusCase>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct UnicodeDataReference {
    pub(crate) version: String,
    pub(crate) facts_file: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct UnicodeFacts {
    pub(crate) facts_format_version: u32,
    pub(crate) unicode_data_version: String,
    pub(crate) known_scalar_ranges: Vec<[u32; 2]>,
    pub(crate) mark_scalar_ranges: Vec<[u32; 2]>,
    pub(crate) token_scalar_ranges: Vec<[u32; 2]>,
    pub(crate) single_scalar_admitted_scalar_ranges: Vec<[u32; 2]>,
    pub(crate) hangul_decomposition: HangulDecomposition,
    pub(crate) compatibility_decomposition_mappings: Vec<(u32, String)>,
    pub(crate) lowercase_mappings: Vec<(u32, String)>,
}

#[derive(Debug, Deserialize, Eq, PartialEq)]
#[serde(deny_unknown_fields)]
pub(crate) struct HangulDecomposition {
    pub(crate) s_base: u32,
    pub(crate) l_base: u32,
    pub(crate) v_base: u32,
    pub(crate) t_base: u32,
    pub(crate) l_count: u32,
    pub(crate) v_count: u32,
    pub(crate) t_count: u32,
}

const STANDARD_HANGUL_DECOMPOSITION: HangulDecomposition = HangulDecomposition {
    s_base: 0xAC00,
    l_base: 0x1100,
    v_base: 0x1161,
    t_base: 0x11A7,
    l_count: 19,
    v_count: 21,
    t_count: 28,
};

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct NormalizationAlgorithm {
    pub(crate) compatibility_decomposition: String,
    pub(crate) stripped_general_categories: Vec<String>,
    pub(crate) token_character_classes: Vec<String>,
    pub(crate) case_folds: Vec<CaseFold>,
    pub(crate) minimum_admitted_scalar_count: usize,
    pub(crate) single_scalar_admitted_scripts: Vec<String>,
    pub(crate) query_token_policy: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct CaseFold {
    pub(crate) from: String,
    pub(crate) to: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct CorpusCase {
    pub(crate) name: String,
    pub(crate) input: String,
    pub(crate) normalized_text: String,
    pub(crate) tokens: Vec<String>,
    pub(crate) query_tokens: Vec<String>,
    pub(crate) admission: String,
}

#[derive(Debug)]
pub(crate) struct LoadedNormalizationContract {
    pub(crate) authority: NormalizationContract,
    pub(crate) unicode_facts: UnicodeFacts,
    pub(crate) decomposition_by_scalar: HashMap<u32, String>,
    pub(crate) lowercase_by_scalar: HashMap<u32, String>,
}

impl LoadedNormalizationContract {
    pub(crate) fn empty() -> Self {
        Self {
            authority: NormalizationContract {
                contract_format_version: 0,
                normalization_version: 0,
                unicode_data: UnicodeDataReference {
                    version: String::new(),
                    facts_file: String::new(),
                },
                algorithm: NormalizationAlgorithm {
                    compatibility_decomposition: String::new(),
                    stripped_general_categories: Vec::new(),
                    token_character_classes: Vec::new(),
                    case_folds: Vec::new(),
                    minimum_admitted_scalar_count: 2,
                    single_scalar_admitted_scripts: Vec::new(),
                    query_token_policy: String::new(),
                },
                corpus: Vec::new(),
            },
            unicode_facts: UnicodeFacts {
                facts_format_version: 0,
                unicode_data_version: String::new(),
                known_scalar_ranges: Vec::new(),
                mark_scalar_ranges: Vec::new(),
                token_scalar_ranges: Vec::new(),
                single_scalar_admitted_scalar_ranges: Vec::new(),
                hangul_decomposition: STANDARD_HANGUL_DECOMPOSITION,
                compatibility_decomposition_mappings: Vec::new(),
                lowercase_mappings: Vec::new(),
            },
            decomposition_by_scalar: HashMap::new(),
            lowercase_by_scalar: HashMap::new(),
        }
    }
}

pub(crate) fn parse_contract(
    source: &str,
    unicode_facts_source: &str,
) -> Result<LoadedNormalizationContract, String> {
    let authority: NormalizationContract =
        serde_json::from_str(source).map_err(|error| error.to_string())?;
    let unicode_facts: UnicodeFacts =
        serde_json::from_str(unicode_facts_source).map_err(|error| error.to_string())?;
    if authority.contract_format_version != 1 {
        return Err("contract format version must equal 1".to_owned());
    }
    if authority.normalization_version == 0 {
        return Err("normalization version must be positive".to_owned());
    }
    validate_unicode_facts(&authority, &unicode_facts)?;
    let decomposition_by_scalar = validate_mappings(
        "compatibility decomposition",
        &unicode_facts.compatibility_decomposition_mappings,
        &unicode_facts.known_scalar_ranges,
    )?;
    let lowercase_by_scalar = validate_mappings(
        "lowercase",
        &unicode_facts.lowercase_mappings,
        &unicode_facts.known_scalar_ranges,
    )?;
    validate_algorithm(&authority.algorithm)?;
    validate_corpus(&authority.corpus)?;
    Ok(LoadedNormalizationContract {
        authority,
        unicode_facts,
        decomposition_by_scalar,
        lowercase_by_scalar,
    })
}

fn validate_algorithm(algorithm: &NormalizationAlgorithm) -> Result<(), String> {
    if algorithm.compatibility_decomposition != "NFKD"
        || algorithm.stripped_general_categories != ["Mn", "Mc", "Me"]
        || algorithm.token_character_classes != ["Letter", "Number", "Underscore"]
        || algorithm.minimum_admitted_scalar_count == 0
        || algorithm.single_scalar_admitted_scripts != ["Han", "Hiragana", "Katakana"]
        || algorithm.query_token_policy != "unique-admitted-or-all-when-active"
    {
        return Err("normalization algorithm uses unsupported semantics".to_owned());
    }
    let mut fold_sources = HashSet::new();
    for case_fold in &algorithm.case_folds {
        if case_fold.from.is_empty()
            || case_fold.to.is_empty()
            || !fold_sources.insert(case_fold.from.as_str())
        {
            return Err("case-fold sources must be nonempty and unique".to_owned());
        }
    }
    Ok(())
}

fn validate_corpus(corpus: &[CorpusCase]) -> Result<(), String> {
    if corpus.is_empty() {
        return Err("normalization corpus must not be empty".to_owned());
    }
    let mut corpus_names = HashSet::new();
    for case in corpus {
        if case.name.is_empty()
            || !corpus_names.insert(case.name.as_str())
            || case.tokens.iter().any(String::is_empty)
            || case.query_tokens.iter().any(String::is_empty)
            || !matches!(
                case.admission.as_str(),
                "browse" | "too-short" | "active-text"
            )
        {
            return Err("normalization corpus is malformed".to_owned());
        }
        let _semantic_case_fields = (&case.input, &case.normalized_text);
    }
    Ok(())
}

fn validate_unicode_facts(
    authority: &NormalizationContract,
    unicode_facts: &UnicodeFacts,
) -> Result<(), String> {
    if authority.unicode_data.version.is_empty()
        || authority.unicode_data.facts_file != UNICODE_FACTS_FILENAME
        || unicode_facts.facts_format_version != 3
        || unicode_facts.unicode_data_version != authority.unicode_data.version
    {
        return Err("Unicode facts do not match the normalization authority".to_owned());
    }
    validate_scalar_ranges("known", &unicode_facts.known_scalar_ranges)?;
    validate_scalar_ranges("mark", &unicode_facts.mark_scalar_ranges)?;
    validate_scalar_ranges("token", &unicode_facts.token_scalar_ranges)?;
    validate_scalar_ranges(
        "single-scalar admitted",
        &unicode_facts.single_scalar_admitted_scalar_ranges,
    )?;
    for [start, end] in &unicode_facts.single_scalar_admitted_scalar_ranges {
        if !scalar_range_is_covered(&unicode_facts.token_scalar_ranges, *start, *end) {
            return Err("single-scalar admitted ranges must contain only token scalars".to_owned());
        }
    }
    for ranges in [
        &unicode_facts.mark_scalar_ranges,
        &unicode_facts.token_scalar_ranges,
    ] {
        for [start, end] in ranges {
            if !scalar_range_is_covered(&unicode_facts.known_scalar_ranges, *start, *end) {
                return Err("Unicode property ranges must contain only known scalars".to_owned());
            }
        }
    }
    validate_hangul(
        &unicode_facts.hangul_decomposition,
        &unicode_facts.known_scalar_ranges,
    )
}

fn validate_hangul(hangul: &HangulDecomposition, known_ranges: &[[u32; 2]]) -> Result<(), String> {
    if hangul != &STANDARD_HANGUL_DECOMPOSITION {
        return Err("Unicode facts must contain the standard Hangul decomposition".to_owned());
    }
    let hangul_scalar_count = hangul
        .l_count
        .checked_mul(hangul.v_count)
        .and_then(|count| count.checked_mul(hangul.t_count))
        .ok_or("Hangul decomposition scalar count overflowed")?;
    let hangul_end = hangul
        .s_base
        .checked_add(hangul_scalar_count)
        .ok_or("Hangul decomposition range overflowed")?;
    if [
        hangul.s_base,
        hangul.l_base,
        hangul.v_base,
        hangul.t_base,
        hangul.l_count,
        hangul.v_count,
        hangul.t_count,
    ]
    .contains(&0)
        || hangul_end > char::MAX as u32 + 1
        || !scalar_range_is_covered(known_ranges, hangul.s_base, hangul_end - 1)
    {
        return Err("Hangul syllable range must contain only known scalars".to_owned());
    }
    Ok(())
}

fn validate_mappings(
    label: &str,
    mappings: &[(u32, String)],
    known_ranges: &[[u32; 2]],
) -> Result<HashMap<u32, String>, String> {
    if mappings.is_empty() {
        return Err(format!("Unicode {label} mappings must not be empty"));
    }
    let mut by_scalar = HashMap::new();
    let mut previous_scalar = None;
    for (scalar, target) in mappings {
        if target.is_empty()
            || previous_scalar.is_some_and(|previous| *scalar <= previous)
            || !scalar_in_ranges(known_ranges, *scalar)
            || target
                .chars()
                .any(|character| !scalar_in_ranges(known_ranges, character as u32))
            || by_scalar.insert(*scalar, target.clone()).is_some()
        {
            return Err(format!(
                "Unicode {label} mappings must be ordered known scalars"
            ));
        }
        previous_scalar = Some(*scalar);
    }
    Ok(by_scalar)
}

fn validate_scalar_ranges(label: &str, ranges: &[[u32; 2]]) -> Result<(), String> {
    if ranges.is_empty() {
        return Err(format!("Unicode {label} scalar ranges must not be empty"));
    }
    let mut previous_end = None;
    for [start, end] in ranges {
        if start > end
            || *end > char::MAX as u32
            || previous_end.is_some_and(|previous| *start <= previous)
            || (*start <= 0xDFFF && *end >= 0xD800)
        {
            return Err(format!(
                "Unicode {label} scalar ranges must be ordered, disjoint scalar values"
            ));
        }
        previous_end = Some(*end);
    }
    Ok(())
}

pub(crate) fn scalar_in_ranges(ranges: &[[u32; 2]], scalar: u32) -> bool {
    let insertion = ranges.partition_point(|[_start, end]| *end < scalar);
    ranges
        .get(insertion)
        .is_some_and(|[start, end]| *start <= scalar && scalar <= *end)
}

fn scalar_range_is_covered(ranges: &[[u32; 2]], start: u32, end: u32) -> bool {
    let mut next_required = start;
    for [range_start, range_end] in ranges {
        if *range_end < next_required {
            continue;
        }
        if *range_start > next_required {
            return false;
        }
        if *range_end >= end {
            return true;
        }
        next_required = *range_end + 1;
    }
    false
}
